export type GraphjinConfigTasksConfig = {
  /** Enable Tasks: Enable durable owner-scoped declared-intent tasks; parsed dev and agentic configs default to enabled when artifacts are enabled */
  enabled?: boolean;
  /** Task Entry Retention Hours: Hours to keep task trail entries before prune-on-write and projection trimming */
  entry_retention_hours?: number;
  /** Max Entries Per Task: Maximum stored trail entries per task; oldest are pruned first */
  max_entries_per_task?: number;
  /** Max Tasks Per Owner: Maximum open tasks per owner */
  max_per_owner?: number;
  /** Task Snapshot Max Bytes: Byte cap for task snapshot_json and task-entry detail_json */
  snapshot_max_bytes?: number;
};

